/* Room-tour reader slip floating over the preview */
.tour-slip-anchor {
  position: absolute;
  z-index: 3;
  width: 0;
  height: 0;
}
.tour-slip {
  position: absolute;
  left: 0;
  translate: -50% 0;
  width: 15.5rem;
  padding: 0.6rem 0.8rem 0.7rem;
  background: var(--color-paper-soft);
  border: 1px solid color-mix(in srgb, var(--color-ink) 20%, transparent);
  border-left: 3px solid var(--slip-accent);
  border-radius: 2px;
  box-shadow: 0 18px 34px -18px
    color-mix(in srgb, var(--shade) 60%, transparent);
  text-align: left;
}
.tour-slip--above {
  bottom: 18px;
}
.tour-slip--below {
  top: 18px;
}
.tour-slip__tag {
  font-family: var(--font-typewriter);
  font-size: 0.66rem;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--slip-accent);
}
.tour-slip__note {
  margin-top: 0.25rem;
  font-family: var(--font-serif);
  font-size: 0.82rem;
  line-height: 1.45;
  color: var(--color-ink-light);
}
.tour-slip__controls {
  margin-top: 0.55rem;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.5rem;
}
.tour-slip__dots {
  display: flex;
  align-items: center;
  gap: 0.3rem;
}
/* Narrow screens: the slip docks as a bottom sheet so it never leaves
   the frame or covers the hotspot it describes. */
@media (max-width: 1023.98px) {
  .tour-slip-anchor {
    left: 50% !important;
    top: auto !important;
    bottom: 0.75rem;
  }
  .tour-slip--above,
  .tour-slip--below {
    top: auto;
    bottom: 0;
  }
  .tour-slip {
    width: min(22rem, calc(100vw - 4rem));
  }
}

/* Room-tour reader card controls */
.tour-step {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 1.6rem;
  height: 1.6rem;
  flex-shrink: 0;
  font-family: var(--font-display);
  font-size: 0.85rem;
  color: var(--color-ink-light);
  border: 1px solid
    color-mix(in srgb, var(--color-ink) 22%, transparent);
  border-radius: 999px;
  background: transparent;
  cursor: pointer;
}
.tour-step:hover {
  color: var(--color-ink);
  border-color: var(--color-vermilion);
}
.tour-step:focus-visible {
  outline: 2px solid var(--color-vermilion);
  outline-offset: 2px;
}
.tour-dot {
  width: 0.5rem;
  height: 0.5rem;
  padding: 0;
  border-radius: 999px;
  border: 1px solid
    color-mix(in srgb, var(--color-ink) 30%, transparent);
  background: transparent;
  cursor: pointer;
}

