import type { EditorialBoardTab } from "./editorial-board-overlay";

/**
 * The Editorial Board's five tabs, shared by the live editor
 * (`src/routes/editor/index.tsx`) and the landing preview
 * (`src/components/landing/workspace-preview.tsx`).
 *
 * One list so the preview can never silently drop, rename, or reorder a
 * tab the room actually has. Add a tab here and both surfaces follow.
 */
export const BOARD_TABS: EditorialBoardTab[] = [
  {
    id: "personas",
    numeral: "I",
    label: "Cast",
    kicker: "Editors in residence",
    accent: "var(--color-vermilion)",
  },
  {
    id: "rubric",
    numeral: "II",
    label: "Rubric",
    kicker: "Dept. of Rigor",
    accent: "var(--color-cobalt)",
  },
  {
    id: "comments",
    numeral: "III",
    label: "Marginalia",
    kicker: "Notes in the margin",
    accent: "var(--color-mustard)",
  },
  {
    id: "citations",
    numeral: "IV",
    label: "Apparatus",
    kicker: "Sources & sourcerers",
    accent: "var(--color-periwinkle)",
  },
  {
    id: "history",
    numeral: "V",
    label: "Versions",
    kicker: "Version history",
    accent: "var(--color-sage)",
  },
];

/**
 * Editorial dateline — formatted like a print magazine masthead.
 * e.g. "Vol. I · No. 117 · Sunday, the 26th of April, 2026"
 *
 * Shared by the live editor masthead and the landing preview so the two
 * never disagree about what the date line looks like.
 */
export function editorialDateline(now = new Date()): string {
  const days = [
    "Sunday",
    "Monday",
    "Tuesday",
    "Wednesday",
    "Thursday",
    "Friday",
    "Saturday",
  ];
  const months = [
    "January",
    "February",
    "March",
    "April",
    "May",
    "June",
    "July",
    "August",
    "September",
    "October",
    "November",
    "December",
  ];
  const day = now.getDate();
  const ordinal = (n: number) => {
    const s = ["th", "st", "nd", "rd"];
    const v = n % 100;
    return n + (s[(v - 20) % 10] || s[v] || s[0]);
  };
  const start = new Date(now.getFullYear(), 0, 0);
  const diff = (now.getTime() - start.getTime()) / 86400000;
  const dayOfYear = Math.floor(diff);
  return `Vol. I · No. ${dayOfYear} · ${days[now.getDay()]}, the ${ordinal(day)} of ${months[now.getMonth()]}, ${now.getFullYear()}`;
}

/** Folio label numerals: Folio I, Folio II, … past X, plain numbers. */
export function folioNumeral(index: number): string {
  return (
    ["I", "II", "III", "IV", "V", "VI", "VII", "VIII", "IX", "X"][index] ??
    String(index + 1)
  );
}

