                  class="mt-4 text-center text-[10px] tracking-[0.14em] uppercase text-[var(--color-ink-muted)]"
                  style="font-family: var(--font-typewriter);"
                >
                  {activeTabMeta?.numeral} · {activeTabMeta?.kicker}
                </p>
              </div>
