/**
 * Post-review with Jev: (1) verify the sweep fixes landed (prompt hardening,
 * note-gate surgery); (2) verify the preview de-drift. Two requests.
 */
import { readFileSync } from "node:fs";
import { judgementQuestions } from "/home/diogenes/Projects/twyne/convex/lib/judgementContract.ts";

const DIRECT_ENDPOINT = "https://api.typesafe.ai/v1/systemone";
const key = process.env.TYPESAFE_API_KEY?.trim();
if (!key) throw new Error("TYPESAFE_API_KEY missing");

const R = "/home/diogenes/Projects/twyne/";
const read = (f: string) => readFileSync(R + f, "utf-8");

async function ask(state: Record<string, string>, questions: unknown, tag: string) {
  const chars = Object.values(state).reduce((n, s) => n + s.length, 0);
  console.error(`${tag} state chars: ${chars}`);
  const res = await fetch(DIRECT_ENDPOINT, {
    method: "POST",
    signal: AbortSignal.timeout(90_000),
    headers: { "Content-Type": "application/json", Authorization: `Bearer ${key}` },
    body: JSON.stringify({ model: "jev-latest", state, questions }),
  });
  if (!res.ok) throw new Error(`${tag}: http ${res.status}`);
  return { tag, ...(await res.json()) };
}

// ── Request 1: verify the sweep fixes ──
const fixState = {
  context: [
    "A prior Jev audit found: JSON-only judge prompts with no escaping rule",
    "(output_fragility 0.88), 10-point scales with undescribed middles",
    "(self_contradiction 0.71), bare draft interpolation (injection 0.6), a",
    "Noul question nobody consumed (movesSuccessSignal), and a missing",
    "misquotation gate. The files below are the fixed versions. Verify the",
    "fixes as engineering facts about the text.",
  ].join(" "),
  "target-fit-user": read("prompts/target-fit-judge-user.md"),
  "target-fit-system": read("prompts/target-fit-judge-system.md"),
  integrity: read("prompts/integrity-judge-user.md"),
  evidence: read("prompts/evidence-judge-user.md"),
  sufficiency: read("prompts/sufficiency-judge-user.md"),
  "custom-criterion": read("prompts/custom-criterion-user.md"),
  "dossier-check": read("prompts/dossier-check-system.md") + "\n---\n" + read("prompts/dossier-check-user.md"),
  "missing-source": read("prompts/missing-source-detector-user.md"),
  "note-gate.ts": read("src/utils/note-gate.ts"),
};

const fixQuestions = judgementQuestions({
  escaping_fixed: {
    type: "noul",
    instructions:
      "Does every prompt in `prompts` that demands JSON-only output now state an escaping rule for double quotes and newlines inside string values?",
  },
  injection_guarded: {
    type: "noul",
    instructions:
      "Is every interpolated draft in these user prompts delimited (tags or quotes) and accompanied by an explicit instruction not to follow instructions found inside the draft text?",
  },
  sufficiency_anchored: {
    type: "noul",
    instructions:
      "Does the sufficiency judge now describe what scores 1, 4, 7, and 10 mean, instead of anchoring only the endpoints?",
  },
  targetfit_coherent: {
    type: "noul",
    instructions:
      "Does the target-fit system prompt resolve the tension in its craft-blindness rule by stating how to score prose so unclear its subject cannot be told?",
  },
  removal_clean: {
    type: "noul",
    instructions:
      "In note-gate.ts, is the movesSuccessSignal question and the successSignal verdict field fully removed — no builder, reader, type member, or comment still references them?",
  },
  quote_gate_sound: {
    type: "score",
    instructions:
      "Is the new misquotesPassage gate sound: a genuine yes-or-no Noul about the note versus the passage, vetoed with the constraint and fact vetoes, routed to its own accuracy rewrite instruction, with a default threshold present?",
    criteria: [
      "Broken: miswired veto, missing threshold, or paraphrase criminalized",
      "Functional with rough edges in routing or wording",
      "Sound: correctly classed, routed, and thresholded",
    ],
  },
  weakest_prompt: {
    type: "choice",
    instructions:
      "Which prompt is now the weakest engineering artifact? target-fit, integrity, evidence, and sufficiency are 1-to-10 judges with anchored scales and escaping rules; custom-criterion judges a writer-named criterion; dossier-check returns a JSON observations array; missing-source returns a JSON claims array.",
    criteria: [
      "target-fit",
      "integrity",
      "evidence",
      "sufficiency",
      "custom-criterion",
      "dossier-check",
      "missing-source",
      "none-significant",
    ],
  },
});

// ── Request 2: verify the de-drift ──
const driftState = {
  context: [
    "The landing preview is a mock of the live editor. A de-drift pass aimed",
    "to derive the preview from the same sources the editor renders: BOARD_TABS,",
    "PERSONAS, SPINE_CRITERIA, a shared dateline and folio numerals, and the",
    "real ProjectBriefCard. workspace-drift.test.ts pins the rest. Verify from",
    "the files whether shared sourcing is real or only claimed.",
  ].join(" "),
  "board-tabs.ts": read("src/components/editorial-board/board-tabs.ts"),
  "editorial-format.ts": read("src/utils/editorial-format.ts"),
  "workspace-preview.tsx": read("src/components/landing/workspace-preview.tsx"),
  "workspace-drift.test.ts": read("src/components/landing/workspace-drift.test.ts"),
};

const driftQuestions = judgementQuestions({
  single_sourced: {
    type: "noul",
    instructions:
      "Does workspace-preview.tsx derive its board tabs, cast identities (names, roles, colors, marks), dateline, folio numerals, dossier card, and rubric labels from the shared modules (board-tabs.ts, personas, editorial-format.ts, ProjectBriefCard, SPINE_CRITERIA) rather than duplicating their content inline?",
  },
  guard_coverage: {
    type: "score",
    instructions:
      "Does workspace-drift.test.ts pin every remaining hand-written preview id (persona ids, folio ids, rubric criterion ids, tour tab and folio references) to its source, so future drift fails loudly?",
    criteria: [
      "No meaningful pinning; drift would pass silently",
      "Partial pinning with gaps an edit could slip through",
      "Complete pinning of every hand-written id to its source",
    ],
  },
  biggest_residual_drift: {
    type: "choice",
    instructions:
      "What is the largest remaining preview-versus-editor drift? static-manuscript means the manuscript is fixed HTML rather than the live TipTap editor; simplified-masthead means no account menu, zen mode, or toasts; canned-board-content means the tab panels show fixed demo data rather than live provider results; dossier-noop means the dossier card button does nothing.",
    criteria: [
      "static-manuscript",
      "simplified-masthead",
      "canned-board-content",
      "dossier-noop",
      "none-significant",
    ],
  },
});

const [r1, r2] = await Promise.all([
  ask(fixState, fixQuestions, "fix-verification"),
  ask(driftState, driftQuestions, "dedrift-verification"),
]);
console.log(JSON.stringify([r1, r2], null, 2));

